def trim_bst(root, low, high):
    if not root:
        return None
    if root.val < low:
        return trim_bst(root.right, low, high)        # discard entire left subtree
    if root.val > high:
        return trim_bst(root.left, low, high)          # discard entire right subtree
    root.left = trim_bst(root.left, low, high)          # trim and reattach in place
    root.right = trim_bst(root.right, low, high)
    return root

