public class Main {
    static TreeNode trimBST(TreeNode root, int low, int high) {
        if (root == null) return null;
        if (root.val < low) return trimBST(root.right, low, high);      // discard entire left subtree
        if (root.val > high) return trimBST(root.left, low, high);        // discard entire right subtree
        root.left = trimBST(root.left, low, high);                          // trim and reattach in place
        root.right = trimBST(root.right, low, high);
        return root;
    }
}

